files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #e0e0e0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: #16213e;
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  border: 1px solid #0f3460;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 24px;
  color: #e94560;
  letter-spacing: 1px;
}

.bpm-control {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 24px;
}

#bpm {
  font-size: 3rem;
  font-weight: 700;
  min-width: 100px;
  color: #f5f5f5;
  font-variant-numeric: tabular-nums;
}

button {
  font-family: inherit;
  font-size: 1.25rem;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  background: #0f3460;
  color: #e0e0e0;
  padding: 12px 20px;
  min-width: 48px;
  min-height: 48px;
}

button:hover:not(:disabled) {
  background: #1a4a7a;
}

button:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

button:active:not(:disabled) {
  transform: scale(0.95);
  background: #0a2a4a;
}

button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

#decrease, #increase {
  font-size: 1.5rem;
  font-weight: 700;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}

.status {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 24px;
}

#beat-counter {
  font-size: 1.25rem;
  color: #a0a0b0;
  font-variant-numeric: tabular-nums;
}

.beat-light {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #2a2a4a;
  border: 2px solid #0f3460;
  transition: background 0.05s, box-shadow 0.05s;
}

.beat-light.active {
  background: #e94560;
  box-shadow: 0 0 20px #e94560;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
}

.controls button {
  flex: 1;
  padding: 16px;
  font-size: 1.25rem;
  font-weight: 600;
}

.primary {
  background: #e94560;
  color: #fff;
}

.primary:hover:not(:disabled) {
  background: #ff5a75;
}

.secondary {
  background: #0f3460;
}

.secondary:hover:not(:disabled) {
  background: #1a4a7a;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  #bpm {
    font-size: 2.5rem;
  }
}

let bpm = 120;
let intervalId = null;
let beatCount = 0;

const bpmDisplay = document.getElementById('bpm');
const decreaseBtn = document.getElementById('decrease');
const increaseBtn = document.getElementById('increase');
const startBtn = document.getElementById('start');
const stopBtn = document.getElementById('stop');
const beatCounter = document.getElementById('beat-counter');
const beatLight = document.getElementById('beat-light');

function updateBpmDisplay() {
  bpmDisplay.textContent = bpm;
}

function flashBeat() {
  beatLight.classList.add('active');
  setTimeout(() => beatLight.classList.remove('active'), 50);
}

function tick() {
  beatCount++;
  beatCounter.textContent = 'Beat: ' + beatCount;
  flashBeat();
}

function start() {
  if (intervalId !== null) return;
  beatCount = 0;
  beatCounter.textContent = 'Beat: 0';
  startBtn.disabled = true;
  stopBtn.disabled = false;
  tick();
  intervalId = setInterval(tick, 60000 / bpm);
}

function stop() {
  if (intervalId === null) return;
  clearInterval(intervalId);
  intervalId = null;
  startBtn.disabled = false;
  stopBtn.disabled = true;
  beatLight.classList.remove('active');
}

function setBpm(newBpm) {
  bpm = Math.min(200, Math.max(40, newBpm));
  updateBpmDisplay();
  if (intervalId !== null) {
    clearInterval(intervalId);
    intervalId = setInterval(tick, 60000 / bpm);
  }
}

decreaseBtn.addEventListener('click', () => setBpm(bpm - 1));
increaseBtn.addEventListener('click', () => setBpm(bpm + 1));
startBtn.addEventListener('click', start);
stopBtn.addEventListener('click', stop);

updateBpmDisplay();
